namespace ghidra.feature.fid.hash;




using ghidra.program.model.address;
using ghidra.program.model.listing;

/**
 * Calculates the function extent by the function body; i.e. what's saved
 * in the database as the body, which could be totally wrong (but then
 * again, so could we, if we try to determine it ourselves).
 *
 */
public class FunctionBodyFunctionExtentGenerator : FunctionExtentGenerator {
	/* @Override */
	public List<CodeUnit> calculateExtent(Function func) {
		if (func == null) {
			return List.of();
		}
		AddressSetView body = func.getBody();
		if (body.isEmpty()) {
			return List.of();
		}
		List<CodeUnit> units = new List<CodeUnit>();

		Program program = func.getProgram();
		Listing listing = program.getListing();

		InstructionIterator codeUnitIterator = listing.getInstructions(body, true);
		foreach (Instruction codeUnit in codeUnitIterator) {
			units.add(codeUnit);
		}

		return units;
	}
}
